using System;
using System.Threading;
using System.Threading.Tasks;
using LastRail.Resources;
using NUnit.Framework;
using UnityEngine;
public sealed class PreparedContentTests {
 [Test] public async Task SharedScopesLoadOnceAndReleaseOnlyLastUser(){var texture=new Texture2D(1,1);int loads=0,releases=0;try{using(var session=new PreparedContent.Session(_=>{loads++;return Task.FromResult(new PreparedContent.AssetLease(texture,()=>releases++));})){var a=await session.PrepareAsync(new[]{"key","key"});var b=await session.PrepareAsync(new[]{"key"});Assert.AreEqual(1,loads);Assert.AreSame(texture,session.Get("key"));a.Dispose();a.Dispose();Assert.AreEqual(0,releases);b.Dispose();Assert.AreEqual(1,releases);Assert.Throws<InvalidOperationException>(()=>session.Get("key"));var c=await session.PrepareAsync(new[]{"key"});Assert.AreEqual(2,loads);c.Dispose();Assert.AreEqual(2,releases);}}finally{UnityEngine.Object.DestroyImmediate(texture);}}
 [Test] public async Task CancelledPreparationReleasesLateResultAndCannotExposeIt(){var texture=new Texture2D(1,1);int releases=0;var pending=new TaskCompletionSource<PreparedContent.AssetLease>();try{using(var session=new PreparedContent.Session(_=>pending.Task))using(var cancel=new CancellationTokenSource()){var operation=session.PrepareAsync(new[]{"key"},cancel.Token);cancel.Cancel();pending.SetResult(new PreparedContent.AssetLease(texture,()=>releases++));try{await operation;Assert.Fail();}catch(OperationCanceledException){}Assert.AreEqual(1,releases);Assert.Throws<InvalidOperationException>(()=>session.Get("key"));}}finally{UnityEngine.Object.DestroyImmediate(texture);}}
 [Test] public async Task PartialFailureReleasesSuccessfulLoadsAndRetryCanSucceed(){var texture=new Texture2D(1,1);int releases=0;bool fail=true;try{using(var session=new PreparedContent.Session(key=>key=="bad"&&fail?Task.FromException<PreparedContent.AssetLease>(new InvalidOperationException("fixture")):Task.FromResult(new PreparedContent.AssetLease(texture,()=>releases++)))){Assert.ThrowsAsync<InvalidOperationException>(async()=>await session.PrepareAsync(new[]{"good","bad"}));Assert.AreEqual(1,releases);fail=false;var next=await session.PrepareAsync(new[]{"good","bad"});Assert.AreSame(texture,session.Get("bad"));next.Dispose();Assert.AreEqual(3,releases);}}finally{UnityEngine.Object.DestroyImmediate(texture);}}
 [Test] public async Task OwnerDisposalRejectsLateCompletionAndReturnsHandle(){var texture=new Texture2D(1,1);int releases=0;var pending=new TaskCompletionSource<PreparedContent.AssetLease>();try{var session=new PreparedContent.Session(_=>pending.Task);var operation=session.PrepareAsync(new[]{"key"});session.Dispose();pending.SetResult(new PreparedContent.AssetLease(texture,()=>releases++));try{await operation;Assert.Fail();}catch(ObjectDisposedException){}Assert.AreEqual(1,releases);}finally{UnityEngine.Object.DestroyImmediate(texture);}}
 [Test] public void UnpreparedLookupDoesNotStartAnyLoad(){int loads=0;using(var session=new PreparedContent.Session(_=>{loads++;throw new Exception();})){Assert.Throws<InvalidOperationException>(()=>session.Get("key"));Assert.AreEqual(0,loads);}}
 [Test] public async Task CancelledScopeDoesNotReleaseReenteredScopeSharingPendingLoad(){var texture=new Texture2D(1,1);int loads=0,releases=0;var pending=new TaskCompletionSource<PreparedContent.AssetLease>();try{using(var session=new PreparedContent.Session(_=>{loads++;return pending.Task;}))using(var cancel=new CancellationTokenSource()){var first=session.PrepareAsync(new[]{"key"},cancel.Token);cancel.Cancel();var second=session.PrepareAsync(new[]{"key"});pending.SetResult(new PreparedContent.AssetLease(texture,()=>releases++));try{await first;Assert.Fail();}catch(OperationCanceledException){}using(var scope=await second){Assert.AreEqual(1,loads);Assert.AreEqual(0,releases);Assert.AreSame(texture,session.Get("key"));}Assert.AreEqual(1,releases);}}finally{UnityEngine.Object.DestroyImmediate(texture);}}
 [Test] public async Task OwnerChangeRejectsPendingPreparationAndReleasesItsAsset(){var texture=new Texture2D(1,1);int releases=0;bool current=true;var pending=new TaskCompletionSource<PreparedContent.AssetLease>();try{using(var session=new PreparedContent.Session(_=>pending.Task,()=>{if(!current)throw new OperationCanceledException();})){var operation=session.PrepareAsync(new[]{"key"});current=false;pending.SetResult(new PreparedContent.AssetLease(texture,()=>releases++));try{await operation;Assert.Fail();}catch(OperationCanceledException){}Assert.AreEqual(1,releases);current=true;Assert.Throws<InvalidOperationException>(()=>session.Get("key"));}}finally{UnityEngine.Object.DestroyImmediate(texture);}}
}
